import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = import.meta.dirname;
const port = 4300 + Math.floor(Math.random() * 500);
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 500));

const errors = [];
try {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));

  await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'load' });
  await page.waitForTimeout(300);

  // rich text check
  const boldOk = await page.$eval('article[data-note-id="1"] .note-body b', (el) => el.textContent.includes('OWASP AppSec Days Porto'));
  const linkHref = await page.$eval('article[data-note-id="4"] .note-body a', (el) => el.getAttribute('href'));
  console.log('bold rendered:', boldOk, 'link href:', linkHref);

  // search
  await page.fill('#search', 'Douro');
  await page.waitForTimeout(200);
  const resultsLine = await page.textContent('#results-line');
  const visibleCount = await page.$$eval('#feed article.note', (els) => els.length);
  console.log('results line:', resultsLine, 'visible count:', visibleCount);

  // deep link via click
  await page.fill('#search', '');
  await page.waitForTimeout(100);
  await page.click('article[data-note-id="3"] .note-title');
  await page.waitForTimeout(100);
  const hash1 = await page.evaluate(() => location.hash);
  const ariaCurrent = await page.getAttribute('article[data-note-id="3"]', 'aria-current');
  console.log('hash after select:', hash1, 'aria-current:', ariaCurrent);

  await page.fill('#search', 'port');
  await page.waitForTimeout(200);
  const hash2 = await page.evaluate(() => location.hash);
  console.log('hash with query+note:', hash2);

  // reload restores
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(300);
  const restoredSearch = await page.inputValue('#search');
  const restoredAria = await page.getAttribute('article[data-note-id="3"]', 'aria-current');
  console.log('restored search value:', restoredSearch, 'restored aria-current:', restoredAria);

  // add note with XSS attempt
  await page.fill('#search', '');
  await page.waitForTimeout(100);
  await page.fill('#title', 'Test <script>window.__xss=1</script>');
  await page.fill('#body', 'Hello <b>world</b>\nnew line <a href="javascript:window.__xss2=1">bad link</a> <a href="https://example.com">good link</a>');
  await page.fill('#avatar', '');
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(200);
  const xssTriggered = await page.evaluate(() => window.__xss || window.__xss2);
  const newNoteCount = await page.$$eval('#feed article.note', (els) => els.length);
  const titleCleared = await page.inputValue('#title');
  const newestTitle = await page.$eval('#feed article.note:first-child .note-title', (el) => el.textContent);
  const badLinkHref = await page.$$eval('#feed article.note:first-child .note-body a', (els) => els.map(a => a.getAttribute('href')));
  console.log('xss triggered:', xssTriggered, 'note count:', newNoteCount, 'title cleared:', titleCleared === '', 'newest title:', newestTitle, 'links:', badLinkHref);

  await browser.close();
} finally {
  server.kill();
}
console.log(errors.length ? 'ERRORS: ' + JSON.stringify(errors) : 'no console errors');

